def test_packing_slip_success(shop):
    oid = shop.orders.handle_create({"customer_id": "c1", "items": [{"sku": "BOOK", "quantity": 2}, {"sku": "PEN", "quantity": 3}]}).body["order_id"]
    response = shop.fulfilment.handle_packing_slip(oid)
    assert response.status == 200
    assert response.body["order_id"] == oid
    assert response.body["customer_name"] == "Ada"
    assert len(response.body["lines"]) == 2
    assert response.body["lines"][0] == {"sku": "BOOK", "name": "Book", "quantity": 2}
    assert response.body["lines"][1] == {"sku": "PEN", "name": "Pen", "quantity": 3}


def test_packing_slip_unknown_order(shop):
    response = shop.fulfilment.handle_packing_slip("ord-9999")
    assert response.status == 404
    assert response.body == {"error": "order not found"}


def test_packing_slip_cancelled_order(shop):
    oid = shop.orders.handle_create({"customer_id": "c1", "items": [{"sku": "BOOK", "quantity": 1}]}).body["order_id"]
    shop.orders.handle_cancel(oid)
    response = shop.fulfilment.handle_packing_slip(oid)
    assert response.status == 409
    assert "cancelled" in response.body["error"]

