            "name": product.name,
            "quantity": item.quantity,
        })

    return Response(200, {
        "order_id": order.order_id,
        "customer_name": customer.name,
        "lines": lines,
    })

def handle_low_stock(self, threshold: Any) -> Response:
    try:
        threshold = require_non_negative_int(threshold, "threshold")
    except InvalidRequest as exc:
        return bad_request(exc)

    products = self._catalog_service.list_active()
    low_stock = []
    for product in products:
        on_hand = self._catalog_service.on_hand(product.sku)
        if on_hand < threshold:
            low_stock.append({
                "sku": product.sku,
                "name": product.name,
                "on_hand": on_hand,
            })

    low_stock.sort(key=lambda p: (p["on_hand"], p["sku"]))

    return Response(200, {"products": low_stock})

